    low=p.lower()
    if any(low.endswith(x) for x in ('.sqlite','.sqlite3','.db','.pem','.p12','.pfx','.key','.zip','.7z','.tar','.gz','.log','.env')):
        suspicious_names.append(p)
    try:
        blob=subprocess.check_output(['git','show',f':{p}'],cwd=repo)
    except subprocess.CalledProcessError:
        continue
    if blob.startswith((b'SQLite format 3\x00',b'PK\x03\x04',b'MZ')):
        binary.append(p)
    text=blob.decode('utf-8','ignore')
    for name,rx in patterns.items():
        for m in rx.finditer(text):
            findings.append({'path':p,'line':text.count('\n',0,m.start())+1,'kind':name})
    for key,value in secret_values:
        pos=text.find(value)
        if pos >= 0:
            findings.append({'path':p,'line':text.count('\n',0,pos)+1,'kind':'matches_formal_secret:'+key})
personal=[]
personal_rx=re.compile(r'49522|E:\\\\Develop\\\\CPA-Stack-Managed|(?<!\d)(?:24544|28984)(?!\d)',re.I)
for p in paths:
